/** Optional Bun + Z3/WASM bridge for the mutation runner.
 *
 * Scope: concrete mutant intervals generated by `generateMutants` on two
 * repository files. It checks the preconditions required by
 * `formal/MutationRunner.lean`, that the empty-expression filter leaves no
 * contained CallExpression mutant, and that the encoding detects planted
 * violations. AST parsing, mutator semantics, process execution and scheduling
 * are not proved here. Not a product or default-CI dependency.
 */
import assert from "node:assert/strict";
import path from "node:path";
import { init, killThreads, type Bool as Z3Bool } from "z3-solver";
import { generateMutants } from "../src/mutation/mutators.ts";
import { applyMutant } from "../src/mutation/apply.ts";
import { mutantTempPath, workerSandboxPath } from "../src/mutation/runner.ts";

const repoRoot = path.resolve(import.meta.dir, "..");
const files = ["src/finding-grouping.ts", "src/cli-option-resolver.ts"];
const api = await init();
try {
  const context = new api.Context("mutation");
  const { Int, Solver, Or, And } = context;
  const solver = new Solver();
  solver.set("timeout", 10_000);

  async function check(formula: Z3Bool<"mutation">, expected: "sat" | "unsat", label: string) {
    solver.reset();
    solver.add(formula);
    const actual = await solver.check();
    assert.equal(
      actual,
      expected,
      `${label}: expected ${expected}, got ${actual}` +
        (actual === "unknown" ? ` (${solver.reasonUnknown()})` : ""),
    );
  }

  let callExpressionTotal = 0;
  for (const file of files) {
    const source = await Bun.file(path.join(repoRoot, file)).text();
    const { mutants } = generateMutants(file, source);
    assert.ok(mutants.length > 0, `${file}: no mutants generated`);

    const preconditionViolations = mutants.map((mutant) =>
      Or(
        Int.val(mutant.start).lt(0),
        Int.val(mutant.end).lt(Int.val(mutant.start)),
        Int.val(mutant.end).gt(Int.val(source.length)),
      ),
    );
    await check(Or(...preconditionViolations), "unsat", `${file}: splice preconditions`);

    for (const mutant of mutants) {
      assert.notEqual(
        source.slice(mutant.start, mutant.end),
        mutant.replacement,
        `${file}:${mutant.start} ${mutant.mutator} is a no-op`,
      );
      const mutated = applyMutant(source, mutant);
      assert.equal(mutated.slice(0, mutant.start), source.slice(0, mutant.start));
      assert.equal(
        mutated.slice(mutant.start + mutant.replacement.length),
        source.slice(mutant.end),
      );
    }

    const contained = mutants.flatMap((candidate, candidateIndex) =>
      candidate.mutator !== "CallExpression"
        ? []
        : mutants.flatMap((other, otherIndex) =>
            otherIndex === candidateIndex
              ? []
              : [And(
                  Int.val(candidate.start).le(Int.val(other.start)),
                  Int.val(other.end).le(Int.val(candidate.end)),
                )],
          ),
    );
    await check(Or(...contained), "unsat", `${file}: empty-expression filter`);
    callExpressionTotal += mutants.filter(
      (mutant) => mutant.mutator === "CallExpression",
    ).length;

    const first = mutants[0]!;
    await check(
      And(
        Int.val(0).le(Int.val(first.start)),
        Int.val(first.end).le(Int.val(source.length)),
      ),
      "sat",
      `${file}: planted containment is detected`,
    );

    await check(
      Or(Int.val(-1).lt(0), Int.val(source.length + 1).gt(Int.val(source.length))),
      "sat",
      `${file}: planted bound violation is detected`,
    );

    console.log(
      `[z3] ${file}: ${mutants.length} mutants, preconditions and filter hold`,
    );
  }
  assert.ok(callExpressionTotal > 0, "no CallExpression mutants were covered");

  const tempRoot = path.join(repoRoot, ".stryker-tmp", "model-root");
  const sandboxes = new Set<string>();
  const tempPaths = new Set<string>();
  for (let worker = 0; worker < 8; worker += 1) {
    const sandbox = workerSandboxPath(tempRoot, worker);
    assert.ok(!sandboxes.has(sandbox));
    sandboxes.add(sandbox);
    for (let index = 0; index < 32; index += 1) {
      const temp = mutantTempPath(tempRoot, worker, index);
      assert.ok(!tempPaths.has(temp), `duplicate temp path ${temp}`);
      assert.ok(
        temp.startsWith(`${tempRoot}${path.sep}tmp${path.sep}worker-${worker}${path.sep}`),
        `temp outside worker root ${temp}`,
      );
      tempPaths.add(temp);
    }
  }
  for (const sandbox of sandboxes) {
    for (const other of sandboxes) {
      if (sandbox !== other) {
        assert.ok(!other.startsWith(`${sandbox}${path.sep}`), "sandbox prefix collision");
      }
    }
  }
  const foreign = path.join(path.dirname(tempRoot), "foreign");
  const owned = [...tempPaths, ...sandboxes];
  assert.equal(owned.filter((entry) => !entry.startsWith(`${tempRoot}${path.sep}`)).length, 0);
  assert.ok(!foreign.startsWith(`${tempRoot}${path.sep}`));

  const K = 32;
  const w1 = Int.const("w1"),
    w2 = Int.const("w2"),
    i1 = Int.const("i1"),
    i2 = Int.const("i2");
  const bounded = And(
    w1.ge(0),
    w1.lt(8),
    w2.ge(0),
    w2.lt(8),
    i1.ge(0),
    i1.lt(K),
    i2.ge(0),
    i2.lt(K),
  );
  await check(
    And(
      bounded,
      w1.mul(K).add(i1).eq(w2.mul(K).add(i2)),
      Or(w1.neq(w2), i1.neq(i2)),
    ),
    "unsat",
    "temp index encoding is injective",
  );
  console.log(
    `[z3] temp paths: ${tempPaths.size} distinct, sandboxes disjoint, owned cleanup complete`,
  );
} finally {
  await killThreads(api.em);
}
